mapper.select:
select ers_id as snapshotId, ers_content_hash as contentHash,
       ers_snapshot_status as snapshotStatus, ers_app_id as appId
from t_ent_resume_snapshot where ers_app_id = #{appId}

mapper.update:
update t_tal
set tal_matched_score = #{score}, tal_updated_at = now()
where tal_id = #{talId}

mapper.select:
select pos_id as positionId, pos_title as title, date_format(pos_updated_at, '%Y-%m-%d %H:%i:%s') as positionVersion, pos_experience_required as experience,
       pos_education_required as education, cast(pos_jd_json as char) as description
from t_pos where pos_id = #{positionId} and pos_company_id = #{companyId}

select cast(asr_report as char) as report,
       asr_snapshot_id as snapshotId,
       asr_content_hash as contentHash,
       asr_version_status as versionStatus,
       date_format(coalesce(asr_created_at, asr_updated_at), '%Y-%m-%d %H:%i:%s') as generatedAt
from t_ai_candidate_analysis
where asr_company_id = #{companyId}
  and asr_position_id = #{positionId}
  and asr_app_id = #{applicationId}
  and asr_candidate_id = #{talId}
  and asr_source = 'llm'
order by asr_created_at desc, asr_updated_at desc, asr_id desc limit 1

select cast(asr_report as char) as report,
       date_format(coalesce(asr_created_at, asr_updated_at), '%Y-%m-%d %H:%i:%s') as generatedAt
from t_ai_candidate_analysis
where asr_company_id = #{companyId}
  and asr_position_id = #{positionId}
  and asr_app_id = #{applicationId}
  and asr_candidate_id = #{talId}
  and asr_source = 'manual'
order by asr_created_at desc, asr_updated_at desc, asr_id desc limit 1

mapper.update:
update t_ai_screening_task set ast_state = #{state}, ast_completed_count = #{completed},
       ast_passed_count = #{passed}, ast_error = #{error}, ast_updated_at = now()
where ast_company_id = #{companyId} and ast_position_id = #{positionId} and ast_run_id = #{runId}

update t_app_record
set app_matched_score = #{score}, app_updated_at = now()
where app_position_id = #{positionId} and app_candidate_id = #{talId}
  and app_status in
#{s}

mapper.select:
select a.app_resume_id
from t_app_record a
join t_pos p on p.pos_id = a.app_position_id
where a.app_position_id = #{positionId} and a.app_candidate_id = #{talId}
  and p.pos_company_id = #{companyId}
limit 1

select count(1)
from t_app_record a
join t_pos p on p.pos_id = a.app_position_id
where a.app_position_id = #{positionId} and a.app_candidate_id = #{talId}
  and p.pos_company_id = #{companyId}

mapper.update:
update t_ai_candidate_analysis
set asr_report = #{report}, asr_updated_at = now()
where asr_id = #{id}
